(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12 + Math.sin((x+y)*0.008+t*0.4)*8;
  const w1y = Math.cos(y*0.016-t*0.22)*16 + Math.sin(x*0.011+t*0.3)*11 + Math.cos((x-y)*0.009-t*0.35)*7;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sx*0.025-t*0.5)*6 + Math.cos(sy*0.03+t*0.6)*4;
  const w2y = Math.cos(sy*0.022+t*0.45)*5 + Math.sin(sx*0.028-t*0.55)*4;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+1)*40, 0.14, 2.1],
    [400+Math.cos(t*0.55+2)*70, 220+Math.sin(t*0.75+4)*50, 0.11, 1.8],
    [200+Math.sin(t*0.25+1)*110, 30+Math.cos(t*0.85)*60, 0.05, 2.8],
    [300+Math.cos(t*0.7+3)*90, 200+Math.sin(t*0.45+2)*70, 0.085, 2.2]
  ];
  let aS=0, iS=0, hS=0;
  for (const [sX,sY,f,sp] of src) {
    const d = Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    hS += Math.sin(d*f*1.3-t*sp*0.4+3.0)*0.5;
  }
  const act=aS/10, inh=iS/10, harm=hS/10;
  const bg = (Math.sin(fx*0.035+fy*0.022+t*0.7)+Math.sin(fx*0.028-fy*0.038+t*1.0))/2
    + Math.sin((fx+fy)*0.1+t*2.2)*0.2 + Math.sin((fx-fy)*0.09-t*1.8)*0.2
    + Math.sin(fx*0.06+fy*0.08-t*1.5)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy,fx-cx);
  const spiral = (Math.sin(dist*0.045-ang*3-t*1.4)+Math.sin(dist*0.035+ang*5-t*1.1)
    +Math.sin(dist*0.06-ang*2+t*0.8)*0.5)*0.35;
  const micro = (Math.sin(fx*0.3)*Math.sin(fy*0.3)+Math.sin(fx*0.22+fy*0.18+t*1.2)*0.6
    +Math.sin(fx*0.4-t*0.8)*Math.cos(fy*0.35+t*0.6)*0.3)/2.2;
  const reaction = Math.tanh((act-inh*0.65+harm*0.35+bg*0.25+spiral+micro*0.15)*2.0);
  const feed = Math.tanh((act*0.5+inh*0.3+harm*0.4)*1.8);
  const coupled = Math.tanh((reaction*0.7+feed*0.3)*2.5);
  const cell = Math.tanh((Math.sin(fx*0.12)*Math.sin(fy*0.12)+Math.sin((fx+fy)*0.08+t)*0.5
    +Math.sin(fx*0.18-fy*0.14+t*0.7)*0.3)*1.4)*0.25;
  const blend = coupled*0.7+cell*0.3, v = blend*0.5+0.5;
  const shift = Math.sin(t*0.15)*0.03;
  const pal = [
    [6,12,58],[10,45,95],[14,85,120],[18,130,135],[45,165,130],
    [130,190,100],[200,185,65],[215,150,60],[200,110,65],[170,65,60],
    [120,35,55],[65,18,48],[30,12,55],[6,12,58]
  ];
  const idx = Math.max(0,Math.min(1,v+shift))*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(coupled*Math.PI)*0.18;
  const edge = Math.abs(coupled)>0.65?1.12:Math.abs(coupled)>0.4?1.04:0.96;
  const glow = Math.max(0, 1-Math.abs(coupled)*1.5)*0.08;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80))|0,
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*120))|0,
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*180))|0
  ];
}
